('4e0bd3c1-1665-42f3-8398-64fd49bb477b','Het Sint Laurensfonds is een kerkelijke stichting verbonden aan het Bisdom Breda. Het fonds verwerft, beheert en besteedt middelen voor rooms-katholieke pastorale zorg binnen de dienst geestelijke verzorging van het Amphia Ziekenhuis, als onderdeel van de diaconale taak van de kerk. Het fonds steunt pastorale zorg en geestelijke verzorging in en vanuit dit ziekenhuis. Doelgroepen zijn patiënten, hun naasten en ziekenhuismedewerkers. Bij de besteding houdt het fonds rekening met de wensen van schenkers en erflaters. Het werkgebied is beperkt tot het Amphia Ziekenhuis in de regio Breda. Het fonds is geen breed open fonds voor externe projectaanvragen.',null,'Het Sint Laurensfonds verwerft en besteedt middelen ten behoeve van rooms-katholieke pastorale zorg binnen de dienst geestelijke verzorging van het Amphia Ziekenhuis.','Breda',null,null,null,'https://bisdombreda.nl/overview/upload/files/ANBI/Sint_Laurensfonds.pdf'),
('0f019357-b5c5-449a-97a1-c93d7284d076','Het Anton Jurgens Fonds is in 1925 opgericht door Anton Jurgens, medeoprichter van Unilever, vanuit ondernemerschap, maatschappelijk bewustzijn en medeleven. Het fonds wil een samenleving bevorderen waarin iedereen kansen krijgt. Het richt zich op sociale ondernemingen in Nederland die mensen met een afstand tot de arbeidsmarkt, of mensen die buiten het arbeidsproces staan, de kans geven maatschappelijk en economisch mee te doen. Het fonds combineert financiering met toegang tot zijn netwerk en zakelijke kennis, zodat sociale ondernemingen kunnen groeien en hun maatschappelijke missie kunnen waarmaken. De portefeuille telt meer dan veertig initiatieven. Trefwoorden: sociaal ondernemerschap, arbeidsparticipatie, inclusieve werkgelegenheid, impactfinanciering en schaalvergroting.',null,'Het Anton Jurgens Fonds bevordert een samenleving met kansen voor iedereen door sociale ondernemingen te steunen die mensen buiten het arbeidsproces laten meedoen.',null,null,null,null,'https://topofminds.com/en/het-anton-jurgens-fonds'),
('3883e612-96fa-456c-b62a-3020dbf0df74','Stichting Benevolentia is een Amsterdams vermogensfonds zonder winstoogmerk dat rooms-katholieke algemene, ideële en culturele belangen behartigt en liefdadigheid beoefent. Het fonds verstrekt wereldwijd financiële giften aan organisaties die menselijke waardigheid en sociale rechtvaardigheid bevorderen, met projecten op het gebied van onderwijs, samenleving, geloof en zorg. Doel is partners in staat te stellen samenlevingen en systemen te bouwen die voor iedereen werken. Het giftenbeleid is gebaseerd op de Katholieke Sociale Leer (onder meer solidariteit, rentmeesterschap, algemeen belang, subsidiariteit en duurzaamheid). Selectie, beoordeling en impactmeting van projecten worden uitgevoerd door Porticus. Het fonds werft zelf geen fondsen; openbare aanvraagvoorwaarden worden niet genoemd.','https://www.stichtingbenevolentia.nl','Behartigen van rooms-katholieke algemene, ideële en culturele belangen en het wereldwijd steunen van organisaties die menselijke waardigheid en sociale rechtvaardigheid bevorderen.','Amsterdam',null,null,null,'https://www.stichtingbenevolentia.nl/_next/static/media/stichting-benevolentia-beleidsplan-2026-2028.pdf'),
('fb5f05ef-ad64-406f-9b51-0b194e95a2b2','Books4Life Amsterdam maakt deel uit van het landelijke netwerk van Books 4 Life-winkels: tweedehands boekwinkels die volledig door vrijwilligers worden gerund. Boeken komen binnen via donaties en inzamelingen (zoals nalatenschappen), worden gesorteerd en verkocht in de winkel of online. De netto-opbrengst gaat naar goede doelen die armoede bestrijden en mensenrechten bevorderen; de belangrijkste begunstigden van het netwerk zijn Amnesty International en Oxfam Novib. Afzonderlijke winkels kunnen daarnaast lokale of kleinere ontwikkelingsprojecten steunen. Het gaat niet om een open fonds met een aanvraagprocedure; de stichting schenkt haar opbrengst aan zelfgekozen organisaties. Specifieke informatie over de begunstigden van de Amsterdamse vestiging is niet gevonden.',null,'Verkoop van tweedehands boeken door vrijwilligers ten bate van goede doelen die armoede bestrijden en mensenrechten bevorderen.','Amsterdam',null,null,null,'https://universonline.nl/?p=33846'),
('dfc7fef6-e816-4148-a136-7ee3aebee928','Stichting Brentano is een Amsterdams vermogensfonds met als doel het bevorderen van het welzijn van ouderen in de breedste zin. Het fonds financiert projecten en initiatieven via vier fondsen: Brentano Brengt Muziek (live muziekoptredens voor ouderen), Brentano Brengt Beweging (projecten die ouderen in beweging brengen, sport en bewegen), Brentano Brengt Cultuur (ouderen in contact brengen met kunst en cultuur) en Brentano Brengt Hulp (acute noodhulp en uitzonderlijke aanvragen die passen bij de doelstelling). Werkgebied is Nederland inclusief de BES-eilanden. Aanvragers doen vooraf een online quickscan; een giftencommissie beoordeelt de aanvragen. Bijdragen zijn in de regel eenmalig en worden vooraf uitbetaald.','https://brentanosteun.nl','Het bevorderen van het welzijn van ouderen in de breedste zin van het woord.','Amsterdam',null,null,null,'https://brentanosteun.nl/wp-content/uploads/2024/08/Brentano-jaarverslag-2023.pdf'),
('70f040d0-b312-4e5e-bd6a-8b8b68e0b5bf','Stichting De Groot Fonds uit Schiedam steunt sociale, maatschappelijke en culturele projecten met een duidelijke lokale of regionale binding, vooral in Schiedam en de regio Waterweg Noord. Het fonds verstrekt eenmalige projectbijdragen en subsidiegaranties, en doet incidenteel maatschappelijke investeringen. Aandachtsgebieden zijn onder meer buurt- en gemeenschapsontwikkeling, ondersteuning van jongeren en ouderen, lokale sport en sociale cohesie, cultureel erfgoed en musea, monumentenzorg en stedelijke vernieuwing. Kwetsbare groepen krijgen bijzondere aandacht. Aanvragers moeten een Nederlandse stichting of vereniging zonder winstoogmerk zijn met geen of beperkt eigen vermogen. Niet gesteund worden individuen, commerciële, politieke of religieuze projecten, exploitatietekorten en overheadkosten. Cofinanciering heeft de voorkeur; aanvragen worden vijf keer per jaar beoordeeld.','https://www.degrootfonds.nl/','Steun aan concrete sociale, maatschappelijke en culturele projecten met aantoonbare maatschappelijke waarde en een lokale binding met Schiedam en omgeving.','Schiedam',null,null,null,'https://www.kindora.co/en/funders/stichting-de-groot-fonds'),
('6bf10904-cd92-45d4-865d-c582d21ddbdd','De Recycling is een kringloopwinkel in ''s-Gravenzande die sinds 1979 gebruikte spullen een tweede leven geeft en draait op zo''n 85 vrijwilligers. De opbrengst wordt via een donatiecommissie geschonken aan lokale stichtingen en organisaties die actief zijn in Westland en Hoek van Holland. Eerder gesteunde projecten betroffen onder meer ondersteuning van mantelzorgers, eenzame jongeren en mensen met schulden, een Sinterklaasviering voor kinderen uit gezinnen met een laag inkomen en dagbesteding voor jongvolwassenen met een licht verstandelijke beperking. Donaties worden uitgereikt tijdens een speciale donatieavond. Een formele aanvraagprocedure of verdere voorwaarden zijn niet gevonden; de belangrijkste voorwaarde is dat de ontvanger regionaal actief is.',null,null,'''s-Gravenzande',null,null,null,'https://www.rodi.nl/westland/nieuws/117766/kringloopwinkel-de-recycling-schenkt-24-000-euro-aan-negen-lokale-stichtingen'),
('a276d632-4d5e-4c6c-b0cf-de508d3e3f9d','Stichting De Verre Bergen is een Rotterdamse stichting zonder winstoogmerk die werkt volgens de principes van venture philanthropy en impact investing. De stichting investeert in innovatieve sociale organisaties en programma''s met als doel Rotterdam beter te maken voor zijn inwoners; het rendement wordt gemeten in maatschappelijke impact op de stad. Inhoudelijke focusgebieden zijn onderwijs en kansenongelijkheid in het onderwijs, schuldenproblematiek en duurzaamheid. Het werkgebied is uitsluitend Rotterdam. Over een open aanvraagprocedure of specifieke doelgroepen is in de gevonden bron niets vermeld.',null,'Investeren in innovatieve sociale organisaties en programma''s om Rotterdam beter te maken voor Rotterdammers, met maatschappelijke impact als rendement.','Rotterdam',null,null,null,'https://magnet.me/en/company/stichting-de-verre-bergen'),
('fdec3771-abbe-4673-ba48-41dc722c5df7','Stichting De Wieringer Schatkamer is een zelfstandige stichting met ANBI-status die de gelijknamige kringloopwinkel in Hippolytushoef (Hollands Kroon) exploiteert. De winkel verkoopt vintage, brocante, huishoudelijke artikelen, kleding en boeken en wordt volledig door vrijwilligers gerund. De stichting is afgesplitst van Stichting Netwerk Roemenië en schenkt het grootste deel van haar opbrengst aan die organisatie, die het geld inzet voor projecten in Roemenië; daarnaast worden goederen voor Roemenië ingezameld. Het gaat niet om een open fonds met een aanvraagprocedure, maar om een kringloopstichting die vooral één vaste partner steunt.',null,null,'Hippolytushoef',null,null,null,'https://www.rodi.nl/hollandskroon/nieuws/348274/ontdek-de-schatkamer-van-wieringen-kringloopwinkel-opent-haar'),
('ecbeeeca-415d-4e02-8b52-3e58819cfdf3','Stichting DOEN werkt aan een groene, sociaal inclusieve en creatieve samenleving en steunt daarvoor voorlopers (pioniers) in de vroegste fase van hun initiatief. Het gaat om ondernemende vernieuwers die met innovatieve oplossingen risico''s nemen en bestaande structuren uitdagen. DOEN werkt op drie terreinen: groen (duurzaamheid), sociaal en creatief (kunst en cultuur), en zet in op het versnellen van transities. Steun bestaat uit giften, leningen en investeringskapitaal (via DOEN Ventures); waar mogelijk worden initiatieven daarna overgedragen aan andere partijen om op te schalen. Het fonds is opgericht door en wordt jaarlijks gefinancierd uit de Nationale Postcode Loterij en de VriendenLoterij. Onder DOEN vallen ook het Postcode Loterij Buurtfonds (bewonersinitiatieven) en het VriendenLoterij Fonds (sociaal ondernemerschap, kunst en cultuur).',null,null,null,null,null,null,'https://www.doen.nl/en/?p=11108'),
('3b461447-28d0-4722-86ba-1df53582f4e6',null,null,null,'Amsterdam',null,null,null,null),
('110dea1a-6fef-4a3b-a01d-e9096bd0b530','Stichting Elizabethfonds uit Boskoop (correspondentieadres Alphen aan den Rijn) heeft als doel hulp te bieden aan mensen in nood, in financiële of in andere vorm. Volgens de oprichtingsakte is er geen beperking ten aanzien van wie in aanmerking komt: de hulp is niet gebonden aan ras, nationaliteit, religie of geslacht. Het werkgebied is wereldwijd. In de gevonden jaarstukken worden geen specifieke projecten, partnerorganisaties, thema''s of aanvraagvoorwaarden genoemd; nadere informatie over het giftenbeleid moet bij de stichting zelf worden opgevraagd.',null,'Hulp bieden aan mensen in nood, financieel of anderszins, zonder onderscheid naar ras, nationaliteit, religie of geslacht, waar ook ter wereld.','Boskoop',null,null,null,'https://www.grantthornton.nl/globalassets/1.-member-firms/netherlands/documenten/diensten/anbi/stichting-elizabethfonds/stichting-elizabethfonds-jaarrekening-2022.pdf'),
('3eff39e0-306e-4c55-a90b-89bafdc35bfc','FNO (zorg voor kansen) is een landelijk vermogensfonds dat ervan uitgaat dat een kwetsbare gezondheid een volwaardig leven niet in de weg mag staan. Het fonds wil kansen vergroten op een betere gezondheid, kwaliteit van leven en toekomstperspectief, door bestaande mogelijkheden te benutten, partners te verbinden, kennis te delen en projecten te financieren via vier programma''s. Doelgroepen zijn gezinnen in een kwetsbare situatie, jongeren met een chronische aandoening, jongvolwassenen met psychische kwetsbaarheid en mensen met een langdurige gezondheidsbeperking. Relevante thema''s zijn onder meer kansengelijkheid in gezondheid, geestelijke gezondheid van jongeren, chronische ziekte, beperking, gezondheid rond zwangerschap en geboorte, onderwijs en verslaving. Werkgebied is Nederland.',null,null,null,null,null,null,'https://health-inequalities.eu/?p=4253'),
('eb91b421-8a24-4ea7-bdde-22d3e0b209bd','Het Amsterdamsche Fonds dient de algemene belangen van Amsterdam door Amsterdamse initiatieven financieel te ondersteunen. Het fonds is nauw verbonden met De Amsterdamsche Kring. Het richt zich op lokale initiatieven en projecten in de stad die weinig of geen steun van andere organisaties ontvangen; zulke projecten krijgen voorrang. De bijdrage bedraagt maximaal 5.000 euro per aanvraag. Inhoudelijke thema''s, specifieke doelgroepen en de aanvraagprocedure worden in de gevonden bron niet nader omschreven.',null,'Het dienen van de algemene belangen van Amsterdam door financiële steun aan Amsterdamse initiatieven.','Amsterdam',null,null,null,'https://www.vca.nu/wp-content/uploads/2022/07/amsterdamse-fondsen.pdf'),
('f010e537-bae3-444f-b647-ff2dac95ff51','Stichting Hulp na Onderzoek is een Amsterdams vermogensfonds dat humanitaire en charitatieve initiatieven steunt die bijdragen aan een inclusief leefklimaat voor alle Amsterdammers. Het fonds financiert kleinschalige, praktische projecten van buurtgerichte stichtingen en verenigingen met direct zichtbaar effect: verbinding, participatie, preventie en basisondersteuning. Thema''s zijn armoedebestrijding, sociale integratie, steun aan vluchtelingen en nieuwkomers, eenzaamheid en welzijn van ouderen, vrijwilligersinitiatieven in de wijk, zorg, preventie en noodhulp. Werkgebied: Amsterdam, Diemen en Duivendrecht. Bijdragen zijn eenmalig (circa 500 tot 15.000 euro, plus een kleine regeling tot 750 euro); één aanvraag per organisatie per jaar. Uitgesloten zijn onder meer louter culturele, milieu-, politieke en wetenschappelijke organisaties, peuterspeelzalen, kinderopvang en scouting.','https://hulpnaonderzoek.nl','Steun aan humanitaire en charitatieve initiatieven die bijdragen aan een inclusief leefklimaat voor alle Amsterdammers.','Amsterdam',null,null,null,'https://www.kindora.co/es/funders/stichting-hulp-na-onderzoek'),
('ff8fcf83-d655-406a-87f1-6e874a22fe4a',null,null,null,'Zeist',null,null,null,null),
('dca5c5d7-5240-4510-91b8-94dcc5a4d8f0','Instituut Gak is een vermogensfonds uit Hilversum dat wil bijdragen aan de kwaliteit van de sociale zekerheid en de arbeidsmarkt in Nederland. Het fonds financiert maatschappelijke projecten van organisaties die mensen met een achterstand op de arbeidsmarkt helpen aan werk, hun arbeidsmogelijkheden versterken of terugval in een uitkering voorkomen. Daarnaast steunt het wetenschappelijk en beleidsgericht onderzoek, programma''s met onderzoeksmonitoring, leerstoelen en lectoraten, en talent via het Instituut Gak Fellowship en de Instituut Gak-KNAW Award voor jonge onderzoekers. Thema''s zijn onder meer arbeidstoeleiding, pensioenen, aansluiting onderwijs-arbeidsmarkt, HRM en arbeid en gezondheid, zowel op stelselniveau als in de uitvoeringspraktijk. Voor projecten is er een digitale quickscan.',null,null,'Hilversum',null,null,null,'https://www.instituutgak.nl/wp-content/uploads/2023/03/Brochure-Instituut-Gak-1-2-2023.pdf'),
('a3918e19-7807-4666-8c62-7e3f1425fe91',null,null,null,'Groningen',null,null,null,null),
('3bc3d4e1-4547-482f-9a09-e565627c10e5','Stichting Levi Lassen is een Nederlands fonds dat zich inzet voor sociale en economische rechtvaardigheid via praktische projecten op gemeenschapsniveau die sociale cohesie, culturele continuïteit en wegen uit armoede en marginalisering versterken. Het fonds kent drie programma''s: Den Haag (organisaties die werken aan sociale en economische rechtvaardigheid voor mensen aan de onderkant van de samenleving; kunstprojecten alleen met een duidelijke doelgroep), Joods Nederland (Joodse gemeenschappen, Joodse identiteit en jongerenprogramma''s) en Israël (empowerment van Ethiopisch-Israëlische jongeren van 15-30 jaar en steun aan oudere Nederlandse immigranten). Bijdragen zijn meestal voor één jaar, in Israël tot circa 15.000 euro, met mogelijke verlenging na evaluatie. Aanvragen minimaal drie maanden voor projectstart indienen.','https://www.levilassen.nl/','Bevorderen van sociale en economische rechtvaardigheid via gemeenschapsgerichte projecten in Den Haag, Joods Nederland en Israël.',null,null,null,null,'https://www.kindora.co/en/funders/stichting-levi-lassen'),
('6e2d91aa-2b45-4b7b-8d05-e5f174725c12',null,null,null,'Amsterdam',null,null,null,null),
('742515b9-1a49-4b59-8be1-6d0bd035b81a','Het Madurodam Kinderfonds uit Den Haag zet zich in voor de persoonlijke ontwikkeling van kinderen en jongeren tot 18 jaar, met nadruk op de leeftijd van 10 tot 16 jaar. Statutair steunt het fonds instellingen met een sociaal, cultureel of charitatief doel voor de jeugd. De missie is kinderen te inspireren zich met anderen te verbinden. Externe organisaties krijgen financiële steun, kennisdeling en hulp bij het leggen van verbindingen. Daarnaast voert het fonds eigen activiteiten uit, zoals een jeugdcollege van burgemeester en wethouders waarin scholieren maatschappelijke opdrachten uitvoeren, de Nationale Kinderherdenking op 4 mei en de Week van Respect. Het werkgebied is het Koninkrijk der Nederlanden: landelijke projecten, Zuid-Holland en ook Curaçao, Aruba en Sint Maarten. Projecten moeten aansluiten bij de doelstelling en de focusgebieden van het fonds; trefwoorden: jeugdparticipatie, burgerschap, verbinding, respect.',null,'Kinderen en jongeren inspireren om zich met anderen te verbinden, door steun aan sociale, culturele en charitatieve initiatieven voor de jeugd.','Den Haag',null,null,null,'https://www.madurodam.nl/sites/madurodam_corp/files/2023-08/MKF-jaarverslag-2022-interactief.pdf'),
('8fb198aa-f315-448d-9cd2-b3bdd893c6fe','Stichting MAX Maakt Mogelijk is verbonden aan Omroep MAX en het gelijknamige tv-programma, en richt zich op het verbeteren van het leven van ouderen in nood, zowel in Nederland als in het buitenland. Voorbeelden van gesteunde projecten zijn winterhulp voor ouderen in Oost-Europa die in slecht geïsoleerde woningen leven, drinkwater voor arme ouderen in Moldavië tijdens hittegolven, een gaarkeuken in Zuid-Afrika, stenen huizen voor grootmoeders in Oeganda die alleen hun kleinkinderen opvoeden, en het vervullen van wensen van ouderen in Nederland. Trefwoorden: ouderen in armoede, noodhulp voor ouderen, huisvesting, voedselhulp, wensvervulling. Aanvraagvoorwaarden zijn in de geraadpleegde bron niet vermeld.',null,'Het leven van ouderen in nood verbeteren, in Nederland en in het buitenland.',null,null,null,null,'https://www.maxvandaag.nl/tag/max-maakt-mogelijk/'),
('eca84563-f744-43c0-9e5e-fbd3c1a0abad','De Stichting Nationaal Rampenfonds (opgericht in 1935, bekend van Giro 777) ondersteunt het herstel van gemeenschappen in Nederland na rampen. Het fonds werft donaties en financiert daarmee kleinschalige, lokale initiatieven voor de mensen die het hardst getroffen zijn. In samenwerking met mensen en organisaties ter plaatse worden de grootste noden in kaart gebracht. Na de overstromingen in Zuid-Nederland, met name in Limburg, ging het geld bijvoorbeeld naar het verwijderen van modder uit huizen en straten en naar urgente reparaties aan woningen en bedrijven. Trefwoorden: rampenhulp, wateroverlast, overstromingen, wederopbouw, lokale hulpinitiatieven, gedupeerden.','https://nationaalrampenfonds.nl/','Gemeenschappen in Nederland helpen herstellen na rampen door lokale hulpinitiatieven te financieren.',null,null,null,null,'https://www.teamlewis.com/nl/ons-werk/stichting-nationaal-rampenfonds/'),
('53317633-173e-460e-ab1a-e1adbd316daf','Stichting Onderwijs Steunfonds, statutair gevestigd in Amsterdam, verleent financiële en andere steun aan organisaties die zich inzetten voor onderwijs, in het bijzonder organisaties met een katholieke identiteit. Het fonds stelt middelen beschikbaar voor onderwijsprojecten en -initiatieven die niet uit de reguliere overheidsbekostiging van onderwijs worden gefinancierd; het bestuur bepaalt de voorwaarden. Het vermogen wordt solide en defensief beheerd en het fonds heeft een ANBI-status met een meerjarig beleidsplan. Trefwoorden: katholiek onderwijs, onderwijsvernieuwing, aanvullende onderwijsfinanciering, scholen, onderwijsprojecten.','https://stos.eu','Financiële en andere steun aan organisaties die zich inzetten voor onderwijs, in het bijzonder met een katholieke identiteit.','Amsterdam',null,null,null,'https://usercontent.one/wp/stos.eu/wp-content/uploads/2022/08/Afschrift-Akte-statutenwijziging-Stichting-Onderwijs-Steunfonds.pdf'),
('b02df1bb-ccda-43d4-8961-0a68f58b14fb','Stichting Pamoefonds is een klein vermogensfonds uit Voorschoten dat jaarlijks giften verstrekt aan de organisaties die in de statuten zijn genoemd. Het jaarverslag over 2025 verwijst naar de kerkenraden van de CGK Leiden, de NGK Oegstgeest en de NGK Leiden, die betrokken waren bij een statutenwijziging; dit wijst op een kerkelijke, gereformeerde achtergrond in de regio Leiden. Een uitgewerkte doelstelling, doelgroep of open aanvraagprocedure staat niet in de geraadpleegde bron; het fonds lijkt vooral vaste, statutair bepaalde begunstigden te steunen. Trefwoorden: kerken, kerkelijke gemeenten, gereformeerd, Leiden, Oegstgeest.',null,null,'Voorschoten',null,null,null,'https://irp.cdn-website.com/5ec79337/files/uploaded/Bestuursverslag+2025+voor+website.pdf'),
('1ec25d5c-9fb4-46b7-8fec-d743498f2a19','Porticus is een internationale filantropische organisatie met hoofdkantoor in Amsterdam die de maatschappelijke betrokkenheid van de familie Brenninkmeijer (oprichters van C&A) voortzet. Het streven is een rechtvaardige en duurzame toekomst waarin menselijke waardigheid tot bloei komt. Als aandachtsgebieden worden onder meer armoede en cultuur en kunst genoemd. Porticus werkt met langdurige financiering voor complexe vraagstukken die tijd nodig hebben, evalueert programma''s flexibel in dialoog met partners en experimenteert en deelt lessen over wat wel en niet werkt. Communicatie verloopt hoofdzakelijk in het Engels. Trefwoorden: systeemverandering, langetermijnfinanciering, menselijke waardigheid, armoedebestrijding, veerkrachtige gemeenschappen.',null,null,'Amsterdam',null,null,null,'https://www.fundraiso.com/en/organisations/porticus-foundation'),
('003affa5-ed43-431c-97df-cbf2b4d8015b','Stichting St. Jansplaats is een vermogensfonds dat werkt vanuit een oud-katholieke, diaconale traditie. Het fonds verleent financiële steun aan mensen die in nood verkeren (behoeftigen) en aan doelen met een (oud-)katholiek of humanitair karakter. Trefwoorden: diaconie, oud-katholieke kerk, hulp aan behoeftigen, humanitaire hulp, kerkelijke projecten. Nadere voorwaarden, werkgebied en aanvraagprocedure konden niet op de website worden geverifieerd; deze beschrijving is gebaseerd op de bestaande missieomschrijving.',null,null,null,null,null,null,'https://www.sintjansplaats.nl/'),
('36a09c66-d15f-48e1-94de-050ae78443e1','Stichting Steunfonds voor Christen Zijn (opgericht in 2009, ANBI) steunt vanuit de Bijbelse opdracht tot naastenliefde christelijke gemeenschappen en organisaties, en maakt humanitaire hulp en noodhulp wereldwijd mogelijk. Het fonds doneert aan organisaties die het best in staat zijn mensen in acute nood te helpen; projecten worden door het bestuur beoordeeld, gevolgd en achteraf geëvalueerd. Structurele buitenlandhulp richt zich vooral op Afrika en Oost-Europa, noodhulp kan overal ter wereld, en lokale hulp gaat naar (Noord-)Nederland. Projecten moeten voldoen aan criteria als toekomstperspectief bieden, inkomen genereren, samenwerken met lokale mensen, verspreiding van Gods Woord, verbetering van gezondheid of leefomstandigheden, of het tegengaan van onrecht.',null,'Christelijke gemeenschappen en organisaties steunen en wereldwijd humanitaire hulp en noodhulp mogelijk maken vanuit naastenliefde.',null,null,null,null,'https://cdn.geef.nl/beleidsplan/document/1622455085_beleidsplan-ssvcz-20-mei-2021.pdf'),
('7e342d42-1715-4dec-ac0a-d30dfff5eddb','Stichting The Dreamery Foundation (opgericht in 2020, ANBI) wil de leefbaarheid van de aarde op lange termijn beschermen voor toekomstige generaties mensen en dieren. Het fonds steunt, financieel of anderszins, initiatieven die klimaatverandering en/of biodiversiteitsverlies tegengaan en die risico''s van geavanceerde technologieën beheersen, zoals AI, biotechnologie en nucleaire technologie. Het werkt volgens de principes van effectief altruïsme. Ondersteund worden jongerenbewegingen, kleinere instellingen en projecten, waaronder wetenschappelijke onderzoeksinstellingen; een belangrijke begunstigde is het Centre for Future Generations. Voorwaarden: concrete en praktische projecten die passen bij het doel, schriftelijke afspraken over doelen, planning en besteding, en periodieke rapportage. Trefwoorden: klimaat, biodiversiteit, AI-veiligheid, biosecurity, toekomstige generaties.','https://dreamery.org','De leefbaarheid van de aarde op lange termijn beschermen voor toekomstige generaties mensen en dieren.',null,null,null,null,'https://dreamery.org/wp-content/uploads/2025/12/20251125-STDF-Beleidsplan-2026-2028.pdf'),
('97738a5c-4fd6-43b0-839a-006092681e22','Het Van Lith-Dumont Fonds is een fonds op naam binnen de Vereniging Rembrandt. Het werd in 2007 opgericht als Fonds voor 20ste-eeuwse Nederlandse Schilderkunst en in 2019 hernoemd. Het fonds ondersteunt Nederlandse musea financieel bij de aankoop van twintigste-eeuwse Nederlandse schilderkunst. Voorbeelden van gesteunde aankopen zijn werken van Piet Mondriaan, Bart van der Leck, Theo van Doesburg en Jan Wiegers, in de categorie moderne kunst (ca. 1880-1950). Aanvragen lopen via de Vereniging Rembrandt. Trefwoorden: museumaankopen, collectievorming, moderne kunst, schilderkunst, kunstaankoop, museale collecties.','https://www.verenigingrembrandt.nl/nl/fonds/van-lith-dumont-fonds','Steun aan Nederlandse musea bij de aankoop van twintigste-eeuwse Nederlandse schilderkunst.',null,null,null,null,'https://www.verenigingrembrandt.nl/nl/fonds/van-lith-dumont-fonds'),
('991da115-6149-4d5f-bb22-f7b77d580048','De Van Teyens Fundatie, gevestigd in het Fundatiehuis in Beetsterzwaag, ondersteunt sportieve, culturele en andere welzijnsactiviteiten in de gemeente Opsterland (Friesland). Het fonds beheert daarnaast landbouwgrond en bossen in de regio. Maatschappelijke organisaties zoals sportverenigingen, muziek- en toneelgroepen kunnen een aanvraag indienen. Voorbeelden van gesteunde projecten: vernieuwing van speeltuinen, voedselpakketten voor de voedselbank, kunsttentoonstellingen, concerten en theaterproducties, en energiebesparende maatregelen bij sportclubs en verenigingen. Aanvragen worden getoetst aan de statuten en op noodzaak; een eigen bijdrage van de aanvrager weegt mee en achteraf wordt verantwoording gevraagd. Trefwoorden: lokale verenigingen, dorpsleven, speeltuin, verduurzaming accommodaties.',null,'Ondersteuning van sportieve, culturele en andere welzijnsactiviteiten in de gemeente Opsterland.','Beetsterzwaag',null,null,null,'https://a.storyblok.com/f/149070/x/ac523741a0/bestuursverslag-vtf-2024-bew-rgb-def-24-5-25.pdf'),
('55106ba4-4a95-457e-b09f-7869fda937e2','The Serco Foundation is een Britse geregistreerde charity (nr. 1150338), verbonden aan het dienstverleningsbedrijf Serco, die subsidies en ondersteuning in natura verstrekt. Volgens de Charity Commission richt de stichting zich op algemene goede doelen en op het bevorderen van gezondheid en het redden van levens. Begunstigden zijn kinderen en jongeren, andere goede doelen en vrijwilligersorganisaties, en het brede publiek; hulp wordt ook geboden in de vorm van menskracht en diensten. Voorbeelden zijn steun aan voedselhulp via Age UK North Tyneside en een subsidie ten behoeve van RAF Brize Norton. Het geregistreerde werkgebied is Hampshire (Verenigd Koninkrijk). Trefwoorden: corporate foundation, lokale charities, gezondheid, defensiegemeenschap.',null,null,null,null,null,null,'https://register-of-charities.charitycommission.gov.uk/en/charity-search/-/charity-details/5033352/what-who-how-where'),
('e5e68fcb-4aab-4aa9-9806-6b58f840f030','De Vitol Foundation is de filantropische stichting van handelsonderneming Vitol, gevestigd in het Verenigd Koninkrijk. De missie is kinderen in deprivatie te helpen de cirkel van armoede te doorbreken zodat zij hun potentieel kunnen bereiken. Het fonds financiert programma''s op het gebied van gezondheid, water, sanitatie en hygiëne (WASH), onderwijs en levensonderhoud (livelihoods), en reageert via vertrouwde partners op humanitaire noodsituaties. Subsidies worden als investeringen benaderd: de voorkeur gaat uit naar programma''s met duurzame, opschaalbare sociale en economische opbrengsten. Het werkgebied is wereldwijd, met onder meer Europa, de landen van het Oostelijk Partnerschap, Afrika, Azië, het Midden-Oosten en Noord-Afrika, en Latijns-Amerika. Trefwoorden: kinderarmoede, WASH, schoon drinkwater, onderwijs, inkomensverwerving.','https://www.vitol.com/vitol-foundation/','Kinderen in deprivatie helpen de cirkel van armoede te doorbreken zodat zij hun potentieel kunnen bereiken.',null,null,null,null,'https://impacteurope.net/members/vitol-foundation'),
('5629b47e-3358-4703-9de0-6ef24236bd32','Het Westfriesland Fonds is een lokaal gemeenschapsfonds dat mensen in de regio West-Friesland wil verbinden. Het steunt concreet afgebakende projecten met maatschappelijke waarde, zoals lokale kunst- en cultuurprojecten, amateurtheater en podiumkunsten, muziek en koren, initiatieven voor kinderen en jongeren, sport- en buurtevenementen, en inclusief wonen en sociale participatie. Bijdragen gaan naar specifieke activiteiten of programmakosten, niet naar exploitatie- of overheadkosten, tekorten of uitsluitend bouw/vastgoed. Aanvragers zijn organisaties (geen particulieren) die in het werkgebied gevestigd zijn of wier project daar plaatsvindt; het project mag nog niet gestart zijn en eigen fondsenwerving is vereist. Commerciële, politieke en religieuze doelen en projecten buiten het werkgebied vallen af. Het accent ligt op Enkhuizen, Bovenkarspel en Grootebroek; aanvragen kan doorlopend.','https://www.westfrieslandfonds.nl/','Lokaal gemeenschapsfonds dat projecten met maatschappelijke waarde ondersteunt die mensen in West-Friesland samenbrengen.','Enkhuizen',null,null,null,'https://www.kindora.co/en/funders/westfriesland-fonds'),
('a16ba87d-a66c-4ec1-b7b8-2b8e832aa639','ZonMw (ZorgOnderzoek Nederland / Medische Wetenschappen) is een publiekrechtelijke intermediaire organisatie die in opdracht van vooral het ministerie van VWS en NWO gezondheidsonderzoek, preventie- en zorgprojecten, experimenten en ontwikkeltrajecten financiert. Het werkveld loopt van fundamenteel medisch onderzoek tot toepassing en implementatie in de praktijk. ZonMw bewaakt de kwaliteit, relevantie en samenhang van de gefinancierde projecten, verbindt wetenschappers, zorgprofessionals, beleidsmakers en patiënten en signaleert nieuwe maatschappelijke en wetenschappelijke vraagstukken en kennislacunes om die op de nationale agenda te zetten. Financiering verloopt via thematische programma''s en subsidieoproepen. Trefwoorden: gezondheidsonderzoek, medisch-wetenschappelijk onderzoek, preventie, zorginnovatie, implementatie van kennis, kennisbenutting in zorg en welzijn.','https://www.zonmw.nl/','ZonMw financiert gezondheidsonderzoek en zorginnovatie en stimuleert het gebruik van kennis, zodat onderzoek leidt tot toepassing in zorg, preventie en gezondheid.','Den Haag',null,null,null,'https://organisaties.overheid.nl/28212246/ZorgOnderzoek_Nederland__Medische_Wetenschappen'),
('bedb1f0e-ee92-44dc-90d5-33fef86e00ec','ZonMw (ZorgOnderzoek Nederland / Medische Wetenschappen) is een publiekrechtelijke intermediaire organisatie die in opdracht van vooral het ministerie van VWS en NWO gezondheidsonderzoek, preventie- en zorgprojecten, experimenten en ontwikkeltrajecten financiert. Het werkveld loopt van fundamenteel medisch onderzoek tot toepassing en implementatie in de praktijk. ZonMw bewaakt de kwaliteit, relevantie en samenhang van de gefinancierde projecten, verbindt wetenschappers, zorgprofessionals, beleidsmakers en patiënten en signaleert nieuwe maatschappelijke en wetenschappelijke vraagstukken en kennislacunes om die op de nationale agenda te zetten. Financiering verloopt via thematische programma''s en subsidieoproepen. Trefwoorden: gezondheidsonderzoek, medisch-wetenschappelijk onderzoek, preventie, zorginnovatie, implementatie van kennis, kennisbenutting in zorg en welzijn.','https://www.zonmw.nl/','ZonMw financiert gezondheidsonderzoek en zorginnovatie en stimuleert het gebruik van kennis, zodat onderzoek leidt tot toepassing in zorg, preventie en gezondheid.','Den Haag',null,null,null,'https://organisaties.overheid.nl/28212246/ZorgOnderzoek_Nederland__Medische_Wetenschappen'),
('df81136d-74c8-4601-af04-7a150fb72d20','De af Jochnick Foundation, in 2004 opgericht door de familie af Jochnick en gevestigd in Schaan (Liechtenstein), steunt internationale organisaties, instellingen en (sociaal) ondernemers met projecten die mensen helpen zelfredzaam te worden. Het fonds geeft subsidies binnen vier gebieden: kinderen en onderwijs, gezondheid en medisch onderzoek, ''onze planeet'' (o.a. landbouw, energie, water, bosbeheer) en duurzame samenlevingen; klimaat is een dwarsdoorsnijdend thema. Er gelden geen eisen aan geografie of type organisatie, wel streeft het fonds naar geografische spreiding. Het treedt op als medefinancier: projecten mogen niet van het fonds afhankelijk zijn, hebben meetbare doelen, een financieringsplan voor na de subsidie en bij voorkeur opschalingspotentieel. Looptijd doorgaans 1-3 jaar, geen giften aan individuen, aanvragen het hele jaar (in het Engels).',null,null,null,null,null,null,'https://ndcpartnership.org/knowledge-portal/climate-funds-explorer/af-jochnick-foundation')
), u as (update public.funders f set
 algemene_beschrijving = coalesce(nullif(f.algemene_beschrijving,''), v.beschr),
 website = coalesce(nullif(f.website,''), v.website),
 missie = coalesce(nullif(f.missie,''), v.missie),
 plaats = coalesce(nullif(f.plaats,''), v.plaats),
 bijdrage_min = coalesce(f.bijdrage_min, v.bmin::numeric),
 bijdrage_max = coalesce(f.bijdrage_max, v.bmax::numeric),
 bijdrage_toelichting = coalesce(nullif(f.bijdrage_toelichting,''), v.btoel),
 bandbreedte_bijdrage_id = coalesce(f.bandbreedte_bijdrage_id, (select b.id from public.bandbreedtes_bijdrage b where coalesce(f.bijdrage_max, v.bmax::numeric) is not null and coalesce(f.bijdrage_max, v.bmax::numeric) > b.bedrag_min and (b.bedrag_max is null or coalesce(f.bijdrage_max, v.bmax::numeric) <= b.bedrag_max) order by b.volgorde limit 1)),
 research_source = coalesce(f.research_source,'') || case when f.research_source is null or f.research_source='' then '' else ' | ' end || 'Verrijking goedgekeurde fondsen ronde12, 17-10-2026 (Claude)',
 last_researched_at = now()
from v where f.id = v.id::uuid returning 1)
select count(*) bijgewerkt from u;